#include "source_material_source_provider_candidate.h"
#include "source_material_patch_files_candidate.h"
#include <iostream>
template<class T>static T read(std::istream&in){T v;if(!in.read(reinterpret_cast<char*>(&v),sizeof(v)))throw std::runtime_error("parser fixture truncated");return v;}
static std::string text(std::istream&in){auto n=read<uint32_t>(in);if(n>(1u<<24))throw std::runtime_error("source extent");std::string s(n,'\0');if(!in.read(s.data(),n))throw std::runtime_error("source truncated");return s;}
template<class T>static void put(std::ostream&out,T v){out.write(reinterpret_cast<const char*>(&v),sizeof(v));}
static void putText(std::ostream&out,const std::string&s){put(out,uint32_t(s.size()));out.write(s.data(),s.size());}
static void writeNode(std::ostream&out,const SourceMaterialPatchNodeCandidate&n){putText(out,n.key);put(out,n.kind);if(n.kind==1)putText(out,n.text);else if(n.kind==2||n.kind==3)put(out,n.bits);else if(n.kind==4||n.kind==7)put(out,n.pointer);put(out,uint32_t(n.children.size()));for(const auto&child:n.children)writeNode(out,child);}


int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"owned material patch x64");if(argc!=3)throw std::runtime_error("mount input output required");std::ifstream in(argv[1],std::ios::binary);std::ofstream out(argv[2],std::ios::binary);if(!in||!out)throw std::runtime_error("fixture streams");auto mountCount=read<uint32_t>(in);if(!mountCount||mountCount>128)throw std::runtime_error("mount extent");std::vector<SourceMaterialSourceMountCandidate>mounts;for(uint32_t i=0;i<mountCount;++i){auto path=text(in),id=text(in);auto position=read<uint32_t>(in);if(position>1)throw std::runtime_error("mount position");SourceMaterialSourceMountCandidate mount{std::filesystem::path(path),id};if(position)mounts.push_back(std::move(mount));else mounts.insert(mounts.begin(),std::move(mount));}SourceMaterialSourceProviderCandidate files(mounts);const auto provider=files.materialSource();auto cases=read<uint32_t>(in);put(out,cases);for(uint32_t i=0;i<cases;++i){auto name=text(in);auto prefix=read<uint32_t>(in);if(prefix>1)throw std::runtime_error("prefix mode");auto value=sourceMaterialPatchFilesCandidate(name,provider,bool(prefix));put(out,uint32_t(1));put(out,uint32_t(value.document.roots.size()));for(const auto&root:value.document.roots)writeNode(out,root);writeNode(out,value.aggregate);}if(in.peek()!=std::char_traits<char>::eof())throw std::runtime_error("fixture trailing bytes");out.flush();if(!out)throw std::runtime_error("output failure");std::cout<<"PASS owned material patch files="<<cases<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
